import 'package:flutter/material.dart';import '../../core/addons/application/addon_install_controller.dart';
class ComponentsPage extends StatelessWidget{const ComponentsPage({required this.addonInstallController,super.key});final AddonInstallController addonInstallController;@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Componentes de addons')),body:AnimatedBuilder(animation:addonInstallController,builder:(_,__){final a=addonInstallController.installedAddons.where((x)=>!x.manifest.isPythonPlugin).toList();if(a.isEmpty)return const Center(child:Text('Nenhum componente instalado'));return ListView(padding:const EdgeInsets.all(24),children:[for(final x in a)Card(margin:const EdgeInsets.only(bottom:10),child:ListTile(leading:const Icon(Icons.extension),title:Text(x.manifest.name),subtitle:Text('${x.manifest.id} • v${x.manifest.version}')))]);}));}
